CREATE TABLE IF NOT EXISTS acp_background_sessions (
  engine TEXT NOT NULL, session_id TEXT NOT NULL, PRIMARY KEY(engine, session_id)
) STRICT, WITHOUT ROWID;
CREATE VIEW IF NOT EXISTS visible_managed_tasks AS
SELECT task.* FROM managed_tasks AS task
WHERE NOT EXISTS (
  SELECT 1 FROM acp_background_sessions AS background
  WHERE background.engine = task.provider AND background.session_id = task.session_id
);
